-- ═══════════════════════════ Hand-written SQL (not expressible in Prisma) ═══════════════════════════

-- Data integrity checks.
ALTER TABLE "organizations" ADD CONSTRAINT "organizations_firm_code_format" CHECK ("firm_code" ~ '^FIRM[0-9]{3,6}$');
ALTER TABLE "financial_years" ADD CONSTRAINT "financial_years_dates" CHECK ("end_date" > "start_date");
ALTER TABLE "financial_years" ADD CONSTRAINT "financial_years_code_format" CHECK ("code" ~ '^[0-9]{4}-[0-9]{2}$' AND "short_code" ~ '^[0-9]{4}$');
ALTER TABLE "users" ADD CONSTRAINT "users_failed_login_count_nonneg" CHECK ("failed_login_count" >= 0);

-- Platform-wide sequence behind firm codes (FIRM001, FIRM002, ...). Numbers are never reused.
CREATE SEQUENCE "organization_code_seq" START WITH 1 INCREMENT BY 1 NO CYCLE;

-- A firm code is permanent: it is embedded in every Case ID of the firm.
CREATE FUNCTION "forbid_firm_code_change"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."firm_code" IS DISTINCT FROM OLD."firm_code" THEN
    RAISE EXCEPTION 'organizations.firm_code is immutable';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "organizations_firm_code_immutable" BEFORE UPDATE ON "organizations"
  FOR EACH ROW EXECUTE FUNCTION "forbid_firm_code_change"();

-- Append-only guard shared by all audit / activity tables.
CREATE FUNCTION "forbid_mutation"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
END $$;
CREATE TRIGGER "audit_logs_append_only" BEFORE UPDATE OR DELETE ON "audit_logs"
  FOR EACH ROW EXECUTE FUNCTION "forbid_mutation"();
CREATE TRIGGER "audit_logs_no_truncate" BEFORE TRUNCATE ON "audit_logs"
  FOR EACH STATEMENT EXECUTE FUNCTION "forbid_mutation"();

-- Runtime role: INSERT/SELECT only on append-only tables (defence in depth on top of the triggers).
-- Guarded so the migration also works on databases without the valuers_app role (e.g. CI).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'valuers_app') THEN
    REVOKE UPDATE, DELETE, TRUNCATE ON "audit_logs" FROM valuers_app;
    GRANT USAGE ON SEQUENCE "organization_code_seq" TO valuers_app;
  END IF;
END $$;
